    {
      "text": "What architectures or frameworks allow LLM agents to interleave reasoning traces with environment actions?"
    },
    {
      "text": "How do reasoning-action interleaving strategies impact the performance of LLM agents in interactive environments?"
    }
  ]
}

{
  "claims": [
    {
      "paper_id": "2210.03629",
      "quote": "In this paper, we explore the use of LLMs to generate both reasoning traces and task-specific actions in an interleaved manner, allowing for greater synergy between the two: reasoning traces help the model induce, track, and update action plans as well as handle exceptions, while actions allow it to interface with external sources, such as knowledge bases or environments, to gather additional information.",
      "claim": "The ReAct framework allows LLM agents to interleave reasoning traces with environment actions to improve planning and information gathering."
    },
    {
      "paper_id": "2210.03629",
      "quote": "On two interactive decision making benchmarks (ALFWorld and WebShop), ReAct outperforms imitation and reinforcement learning methods by an absolute success rate of 34% and 10% respectively, while being prompted with only one or two in-context examples.",
      "claim": "Interleaving reasoning and acting significantly improves the success rate of LLM agents in interactive decision-making environments compared to standard imitation and reinforcement learning methods."
    },
    {
      "paper_id": "2602.01672",
      "quote": "Search-augmented reasoning agents interleave multi-step reasoning with external retrieval, but uncontrolled retrieval can introduce redundant evidence, saturate the context, and destabilize reinforcement learning (RL).",
      "claim": "Uncontrolled interleaving of reasoning and retrieval can negatively impact agent performance by introducing redundant information and destabilizing reinforcement learning."
    },
    {
      "paper_id": "2602.01672",
      "quote": "We propose DeepControl, an adaptive information-control framework based on information utility, a state-dependent estimate of the marginal value of retrieved evidence. The framework regulates information acquisition along two axes: extent, i.e., whether retrieval should continue, and resolution, i.e., how much retrieved detail should be exposed.",
      "claim": "The DeepControl framework improves agent performance by adaptively regulating the extent and resolution of information retrieved during interleaved reasoning."
    }
  ]
}

